/* eslint-disable react/display-name */
import React from 'react';
import { connect } from 'react-redux';
import Paper from '@material-ui/core/Paper';
import Tab from '@material-ui/core/Tab';
import Tabs from '@material-ui/core/Tabs';
import HowToRegIcon from '@material-ui/icons/HowToReg';
import { store } from '../../../index.js';
import { setCommonParam, setStoreActiveTab, setVisitedCourseId } from '../../../actions/admin/auth.js';
import PeopleAltIcon from '@material-ui/icons/PeopleAlt';
import SwapVertIcon from '@material-ui/icons/SwapVert';

// Material UI
import { ScrollTabPanel } from '../Reports/index.js';
import { Card } from '@material-ui/core';
import Loadable from 'react-loadable';
import AppBackdrop from 'layouts/Backdrop';
import { withRouter } from 'react-router-dom';
import colors from 'config/colors.js';
import constants, { employeeStatic, courseStatic } from 'config/constants.js';

const tabList = [
  { tabIndex: 0, tabTitle: 'Students', query: 'school-students', icon: <PeopleAltIcon /> },
  // Shown in this order (Students, Switch class, Guardians); tabIndex stays each tab's stable id.
  {
    tabIndex: 2,
    tabTitle: 'Switch class',
    query: 'switch-class',
    icon: <SwapVertIcon />,
    // The move-students-course API is admin-only on the backend, so teachers don't get the tab.
    roles: [constants.roles.SA, constants.roles.admin],
  },
  { tabIndex: 1, tabTitle: 'Guardians', query: 'guardians', icon: <HowToRegIcon /> },
];

const StudentsPage = withRouter(
  Loadable({
    loader: () => import('views/admin/Students/StudentsPage.jsx'),
    loading: () => <AppBackdrop isOpen={true} />,
  })
);

const SwitchClassPanel = Loadable({
  loader: () => import('views/admin/Students/components/SwitchClassPanel.jsx'),
  loading: () => <AppBackdrop isOpen={true} />,
});

const GuardianPage = withRouter(
  Loadable({
    loader: () => import('views/admin/Guardian/GuardianPage'),
    loading: () => <AppBackdrop isOpen={true} />,
  })
);

export const empOrCourseEmptyDiv = (
  <Card>
    <div className="p-3 font-weight-bold text-center" style={{ color: 'red', fontSize: 15 }}>
      Either {employeeStatic} or {courseStatic} is Empty
    </div>
  </Card>
);

export const passActiveTabAndCourseId = (activeTab, courseId) => {
  activeTab && store?.dispatch(setStoreActiveTab(activeTab));
  activeTab && courseId && store?.dispatch(setVisitedCourseId({ activeTab, courseId }));
};

class MyStudents extends React.Component {
  isLoading = (name, value) => {
    this.setState({
      [name]: value,
    });
  };

  componentDidMount() {
    const { search = null } = this.props?.location || {};
    if (search) {
      const cTab = tabList.find(dto => search.includes(dto.query));
      if (cTab) {
        this.toggleActivityTab(null, cTab.tabIndex);
      } else {
        this.toggleActivityTab(null, 0);
      }
    } else {
      this.toggleActivityTab(null, 0);
    }
  }

  toggleActivityTab = (event, tabIndex) => {
    if (tabIndex !== undefined && this.props.schooActiveTab !== tabIndex) {
      setCommonParam('studentActiveTab', tabIndex);
      const cTab = tabList.find(dto => dto.tabIndex === tabIndex);
      if (cTab) {
        this.props.history.push(`${this.props.location.pathname}?${cTab.query}`);
      }
    }
  };

  render() {
    const { loggedUserRole, studentActiveTab } = this.props;
    const visibleTabs = tabList.filter(item => !item.roles || item.roles.includes(loggedUserRole));
    // A stored tab this role can't see (e.g. left on Switch class by another login) falls back to Students.
    const activeTab = visibleTabs.some(item => item.tabIndex === studentActiveTab) ? studentActiveTab : 0;
    return (
      <div className="content">
        <Paper square>
          <Tabs
            value={activeTab}
            onChange={(e, tabIndex) => this.toggleActivityTab(e, tabIndex)}
            indicatorColor=""
            textColor="inherit"
            variant="fullWidth"
            scrollButtons="on"
            aria-label="scrollable force tabs example">
            {visibleTabs.map(item => {
              return (
                <Tab
                  key={item.tabIndex}
                  value={item.tabIndex}
                  icon={item?.icon}
                  label={item.tabTitle}
                  style={{
                    fontWeight: 'bold',
                    color: activeTab === item.tabIndex ? colors.accent : '',
                    borderBottom: activeTab === item.tabIndex ? `3px solid ${colors.accent}` : '',
                  }}
                />
              );
            })}
          </Tabs>
        </Paper>
        <ScrollTabPanel value={activeTab} index={0}>
          <br />
          <StudentsPage />
        </ScrollTabPanel>
        <ScrollTabPanel value={activeTab} index={1}>
          <br />
          <GuardianPage />
        </ScrollTabPanel>
        {visibleTabs.some(item => item.tabIndex === 2) && (
          <ScrollTabPanel value={activeTab} index={2}>
            <br />
            <SwitchClassPanel />
          </ScrollTabPanel>
        )}
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    studentActiveTab: state.auth.studentActiveTab,
  };
};

export default connect(mapStateToProps)(MyStudents);
